package dev.localllm.harness.application.model;

/**
 * Token counters reported by the model server for one turn.
 *
 * @param promptTokens tokens of the prompt processed by the model
 * @param completionTokens tokens generated by the model, including thinking
 */
public record TokenUsage(int promptTokens, int completionTokens) {

  /** Usage of a turn for which the server reported no counters. */
  public static final TokenUsage EMPTY = new TokenUsage(0, 0);
}
